import {chartScenarios as scenarios,streets} from './chart-scenarios.js';
import {profileFor} from './profiles.js';
import {HAND_CELLS,chartContext,gradeChart,reasonForHand,validateSelection} from './chart-engine.js';
import {ensureChartProgress,recordChartAttempt} from './chart-progress.js';
import {explainHand} from './hand-explanations.js';
import {buildSpotQuestion,codexDraftUrl} from './spot-question.js';
import {libraryInfo,situationNames,styleNames,filterScenarios,sessionOrder} from './scenario-library.js';
const scenarioById=new Map(scenarios.map(s=>[s.id,s]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',book:'<path d="M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15"/>',repeat:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',chart:'<path d="M4 20V10m8 10V4m8 16v-7"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7l1-8Z"/>',bulb:'<path d="M9 18h6m-5 3h4M8 14a7 7 0 1 1 8 0l-1 2H9Z"/>',shuffle:'<path d="M3 5h3c4 0 8 14 12 14h3M3 19h3c2 0 4-4 6-7s4-7 6-7h3m-4-4 4 4-4 4m0 6 4 4-4 4"/>',check:'<path d="m5 12 4 4L19 6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4 2c-1 .5-1.5 1-1.5 2m0 3v.5"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const symbols={s:'♠',h:'♥',d:'♦',c:'♣'};
const suitNames={s:'spades',h:'hearts',d:'diamonds',c:'clubs'};
const rankNames={T:'10',J:'jack',Q:'queen',K:'king',A:'ace'};
const cardName=c=>`${rankNames[c[0]]||c[0]} of ${suitNames[c[1]]}`;
const card=(c,small=false)=>c?`<div class="playing-card ${/[hd]/.test(c[1])?'red':''} ${small?'small':''}" role="img" aria-label="${cardName(c)}"><span class="rank">${c[0]==='T'?'10':c[0]}</span><span class="suit">${symbols[c[1]]}</span><span class="corner">${symbols[c[1]]}</span></div>`:'<div class="playing-card empty" role="img" aria-label="Unrevealed board card">·</div>';
const inlineCard=c=>`<span class="${/[hd]/.test(c[1])?'mini-red':''}" aria-label="${cardName(c)}">${c[0]==='T'?'10':c[0]}${symbols[c[1]]}</span>`;
const combo=c=>c.map(inlineCard).join(' ');
const handLabel=t=>t.length===4?combo([t.slice(0,2),t.slice(2)]):t;
const STORAGE='combo-lab-progress-v1';
let storageOK=true;
function load(){try{const value=JSON.parse(localStorage.getItem(STORAGE));if(value?.version===1&&Array.isArray(value.attempts)&&value.records)return ensureChartProgress(value)}catch{}return ensureChartProgress({version:1,attempts:[],records:{}})}
let progress=load();
let state={view:'train',street:'all',collection:'all',style:'all',difficulty:'all',situation:'all',unseen:false,sessionLength:null,sessionDone:false,sessionScores:[],librarySearch:'',index:0,order:scenarios.map(s=>s.id),selected:[],undo:[],result:null,inspected:null,hinted:false,showHint:false,error:'',shuffle:false,round:1,confirmReset:false,coachOpen:false,coachHand:'',coachQuestion:'',coachStatus:''};
let reviewCurrent=null;
const pool=()=>state.order.map(id=>scenarioById.get(id)).filter(Boolean);
const queue=()=>scenarios.filter(s=>progress.chart.records[s.id]?.review);
const current=()=>state.sessionDone&&state.view==='train'?null:state.view==='review'?(reviewCurrent||queue()[0]):pool()[state.index%Math.max(pool().length,1)];
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(progress))}catch{storageOK=false}}
function clearQuestion(){state.coachOpen=false;state.coachHand='';state.coachQuestion='';state.coachStatus='';state.selected=[];state.undo=[];state.result=null;state.inspected=null;state.hinted=false;state.showHint=false;state.error=''}
function stats(){const attempts=progress.chart.attempts;let streak=0;for(let i=attempts.length-1;i>=0;i--){const a=attempts[i];if(a.correct&&!a.hinted&&!a.revealed)streak++;else break}const completed=attempts.filter(a=>!a.revealed);return{total:attempts.length,average:completed.length?Math.round(completed.reduce((n,a)=>n+a.score,0)/completed.length):null,streak,mastered:scenarios.filter(s=>progress.chart.records[s.id]?.mastered).length}}
function nav(view){if(view==='train'&&state.sessionDone)rebuildOrder();state.view=view;state.confirmReset=false;clearQuestion();reviewCurrent=view==='review'?queue()[0]:null;render();window.scrollTo({top:0,behavior:'instant'})}
function rebuildOrder(){const eligible=filterScenarios(scenarios,state,progress.chart.records);state.order=state.shuffle?sessionOrder(eligible,Date.now()):eligible.map(s=>s.id);state.index=0;state.round=1;state.sessionLength=null;state.sessionDone=false;state.sessionScores=[];clearQuestion()}
function setStreet(street){state.street=street;rebuildOrder();render()}
function startSession(){const eligible=filterScenarios(scenarios,state,progress.chart.records);state.order=sessionOrder(eligible,Date.now()).slice(0,20);state.sessionLength=state.order.length;state.sessionDone=false;state.sessionScores=[];state.view='train';state.index=0;state.round=1;clearQuestion();render();window.scrollTo({top:0,behavior:'instant'})}
function openScenario(id){if(!scenarioById.has(id))return;Object.assign(state,{street:'all',collection:'all',style:'all',difficulty:'all',situation:'all',unseen:false,sessionLength:null,sessionDone:false,sessionScores:[],shuffle:false,order:scenarios.map(s=>s.id)});state.index=state.order.indexOf(id);nav('train')}

function recordSelection(hands){state.undo.push([...state.selected]);if(state.undo.length>100)state.undo.shift();state.selected=[...hands];state.error='';updateChart()}
function toggleHand(hand){const s=current();if(!s)return;state.inspected=hand;if(state.result){updateInspector();return}if(!chartContext(s).legal.has(hand)){updateInspector();return}recordSelection(state.selected.includes(hand)?state.selected.filter(h=>h!==hand):[...state.selected,hand])}
function submit(reveal=false){const s=current();if(!s||state.result)return;if(!reveal&&!state.selected.length){state.error='Choose at least one hand on the chart, then check your range.';render();return}const result=gradeChart(s,state.selected);state.result={...result,revealed:reveal};recordChartAttempt(progress,{id:s.id,result,hinted:state.hinted,revealed:reveal});if(state.sessionLength&&state.view==='train')state.sessionScores[state.index]=reveal?0:result.score;state.inspected=result.extra[0]||result.missing[0]||result.matched[0]||null;save();render();document.querySelector('#chart-feedback')?.focus({preventScroll:true})}
function next(){clearQuestion();if(state.view==='review'){const q=queue();const i=q.findIndex(s=>s.id===reviewCurrent?.id);reviewCurrent=q.length?q[(i+1)%q.length]:null}else{state.index++;if(state.index>=pool().length){if(state.sessionLength)state.sessionDone=true;else if(state.unseen){const round=state.round+1;rebuildOrder();state.round=round}else{state.index=0;state.round++}}}render();window.scrollTo({top:0,behavior:'instant'})}
function compare(id){openScenario(id)}
function shuffle(){state.shuffle=!state.shuffle;rebuildOrder();render()}
function render(){const st=stats(),view=state.view,title={train:'Range practice',review:'Mistake review',library:'Scenario library',lessons:'Field guide',progress:'Your progress'}[view];
 document.querySelector('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brand-mark" aria-hidden="true">◈</span><div class="brand-name">COMBO <span>LAB</span></div></div><div class="side-label">Your study room</div><nav class="nav" aria-label="Main navigation">${[['train','grid','Range practice'],['library','target','Scenario library'],['lessons','book','Field guide'],['review','repeat','Mistake review'],['progress','chart','Your progress']].map(([v,i,l])=>`<button data-nav="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''} aria-label="${l}">${icon(i)}<span class="nav-label">${l}</span>${v==='review'&&queue().length?`<span class="badge">${queue().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="study-note"><b>Think in ranges.</b>Read the player. Follow the bets. Choose the hands.</div><div class="profile"><span class="avatar">♠</span><span>Your poker notebook<small>50–100bb · No-limit hold’em</small></span></div></div></aside><div class="main-wrap"><header class="topbar"><div class="crumb">Study room <span class="slash">/</span> <strong>${title}</strong></div><div class="top-meta"><span class="streak">${icon('bolt')} ${st.streak} in a row</span><span>6-max cash</span></div></header><main id="main" class="main">${!storageOK?'<p class="alert">This browser could not save progress. You can still practice in this session.</p>':''}${view==='lessons'?lessonsView():view==='progress'?progressView():view==='library'?libraryView():trainingView()}<footer class="footer"><span>Feedback compares your read with an illustrative working model, not a solved or certain range.</span><button data-nav="progress">Progress saved in this browser</button></footer></main></div></div>`;
 bind();
}
function trainingView(){if(state.sessionDone&&state.view==='train')return sessionSummary();const s=current(),review=state.view==='review';if(!s)return `<div class="empty-state"><div class="empty-icon">${icon('check')}</div><h1>${review?'A clean slate.':'No spots match these filters.'}</h1><p>${review?'No range charts are waiting for review. Missed or assisted attempts appear here until you complete them without help.':'Reset the filters or include practiced hands to continue.'}</p><button class="primary" data-action="all-hands">Keep practicing</button></div>`;
 const index=review?scenarios.findIndex(x=>x.id===s.id)+1:state.index+1;
 return `<div class="title-row"><div><h1>${review?'Rebuild your read.':'Build villain’s range.'}</h1><p class="subtitle">Read the tendencies and bets. Click every hand that could be in villain’s range.</p></div><div class="title-actions"><button class="outline-button" data-ask="">Ask Codex ↗</button><button class="outline-button" data-nav="lessons" aria-label="Chart guide">${icon('book')}<span class="button-label">Chart guide</span></button></div></div>${review?`<p class="review-callout">${queue().length} chart${queue().length===1?'':'s'} left to revisit. A complete match without help clears a chart.</p>`:`<div class="filters"><div class="segmented" aria-label="Street filter">${Object.entries(streets).filter(([k])=>k==='all'||scenarios.some(s=>s.street===k)).map(([k,v])=>`<button data-street="${k}" class="${state.street===k?'active':''}" aria-pressed="${state.street===k}">${v}</button>`).join('')}</div><button class="outline-button" data-action="shuffle" aria-pressed="${state.shuffle}">${icon('shuffle')}${state.shuffle?'Shuffled order':'Shuffle hands'}</button></div>`}${!review?libraryControls():''}${state.round>1&&!review?`<p class="fresh-round">Round ${state.round}. Rebuild the ranges from what you remember.</p>`:''}<div class="range-workspace"><div class="scenario-column">${handView(s,index)}${villainProfile(s)}</div>${chartView(s)}</div>${state.result?solutionView(s):''}${coachView(s)}`;
}
function libraryControls(){return `<section class="library-controls" aria-label="Practice filters"><div class="library-intro"><span><b>${scenarios.length.toLocaleString()} spots</b> · ${libraryInfo.recipes} model recipes · ${libraryInfo.runouts} board runouts</span><button class="text-button" data-nav="library">Browse library ↗</button></div><div class="library-filter-row">${[['collection','Collection',{all:'All spots',guided:'10 guided exercises',expanded:'Expanded library'}],['style','Opponent',{all:'All tendencies',...styleNames}],['difficulty','Difficulty',{all:'All levels',Foundation:'Foundation',Applied:'Applied',Advanced:'Advanced'}],['situation','Situation',{all:'All situations',guided:'Guided examples',...situationNames}]].map(([key,label,values])=>`<label>${label}<select data-filter="${key}" aria-label="${label}">${Object.entries(values).map(([v,l])=>`<option value="${v}" ${state[key]===v?'selected':''}>${l}</option>`).join('')}</select></label>`).join('')}</div><div class="library-session-row"><label class="unseen-toggle"><input type="checkbox" data-unseen ${state.unseen?'checked':''}> Only unpracticed spots</label><span>${state.sessionLength?`${state.sessionLength}-hand session`:`${pool().length.toLocaleString()} spots in this set`}</span><button class="outline-button" data-action="start-session">Start a shuffled 20-hand session</button></div><p class="library-scope">Generated practice uses explicit tendency models, not solver solutions. Board, position, action, and hole-card variations are counted as spots.</p></section>`}
function sessionSummary(){const mean=state.sessionScores.length?Math.round(state.sessionScores.reduce((a,b)=>a+b,0)/state.sessionScores.length):0;return `<section class="session-summary"><span class="eyebrow">Session complete</span><h1>${state.sessionScores.length} ranges practiced.</h1><p class="subtitle">${mean}% average range match for this session. Revealed ranges count as 0% here.</p><div class="session-summary-actions"><button class="primary" data-action="start-session">Start another 20</button><button class="outline-button" data-nav="review">Review mistakes</button><button class="outline-button" data-nav="library">Browse the library</button></div><p class="formula-note">Your results and any ranges that need review are saved in this browser.</p></section>`}
function libraryResults(){const q=state.librarySearch.trim().toLowerCase(),matches=scenarios.filter(s=>`${s.id} ${s.title} ${s.street} ${s.style} ${s.heroPosition} ${s.villainPosition}`.toLowerCase().includes(q));return `<p class="library-result-count">${matches.length.toLocaleString()} spots found${matches.length>24?' · showing the first 24':''}</p><div class="spot-grid">${matches.slice(0,24).map(s=>`<button class="spot-card" data-open-spot="${s.id}"><span class="eyebrow">${streets[s.street]} · ${s.difficulty}</span><strong>${escape(s.title)}</strong><span>${s.heroPosition} vs ${s.villainPosition} · ${styleNames[s.style]||'Guided'} · ${s.effectiveStackBB||50}bb</span><span class="spot-id">${s.id}</span><span>${progress.chart.records[s.id]?.mastered?'✓ Complete match':progress.chart.records[s.id]?.attempts?'Practiced · retry':'New spot'} →</span></button>`).join('')}</div>${matches.length?'':'<p>No spots match that search. Try a street, board texture, position, or spot ID.</p>'}`}
function libraryView(){return `<div class="title-row"><div><h1>A bigger poker study room.</h1><p class="subtitle">Build ranges across positions, textures, betting lines, and opponent tendencies.</p></div><button class="outline-button" data-nav="train">Back to practice</button></div><div class="library-stats"><div><b>${scenarios.length.toLocaleString()}</b><span>Playable spots</span></div><div><b>${libraryInfo.recipes}</b><span>Situation / style recipes</span></div><div><b>${libraryInfo.runouts}</b><span>Board runouts</span></div><div><b>10</b><span>Guided exercises retained</span></div></div><p class="library-scope">${libraryInfo.generated.toLocaleString()} generated spots use ${libraryInfo.templates} board-specific templates and varied legal hole cards. These are transparent teaching models, not independently authored quizzes or solver outputs.</p><div class="street-library">${Object.entries(streets).filter(([k])=>k!=='all').map(([k,l])=>`<button class="outline-button" data-library-street="${k}"><b>${l}</b><span>${scenarios.filter(s=>s.street===k).length.toLocaleString()} spots →</span></button>`).join('')}</div><label class="library-search-label" for="library-search">Find a spot by title, street, position, or ID</label><input id="library-search" type="search" placeholder="Try paired, check-raise, river, or CO…" value="${escape(state.librarySearch)}"><div id="library-results">${libraryResults()}</div>`}
function bindSpotLinks(){document.querySelectorAll('[data-open-spot]').forEach(el=>el.onclick=()=>openScenario(el.dataset.openSpot))}
function handView(s,index){return `<section class="hand-panel compact-hand" aria-label="Hand scenario"><div class="hand-top"><span class="hand-title"><span class="small-pill">${streets[s.street]}</span>${state.sessionLength&&state.view==='train'?'Session':'Spot'} ${String(index).padStart(2,'0')} / ${state.view==='review'?scenarios.length:pool().length}</span><span class="muted">${s.effectiveStackBB||50}bb stacks</span></div><div class="table-scene"><div class="poker-table"></div><div class="seat villain-seat"><span class="seat-label"><b>Villain</b> · ${s.villainPosition}</span></div><div class="dealer ${s.heroPosition==='BTN'?'hero-dealer':s.villainPosition==='BTN'?'':'off-table'}" title="Dealer button">D</div><div class="board-wrap"><div class="pot">Pot after villain’s bet <b>${s.potAfterBet}bb</b></div><div class="board" aria-label="Community cards">${[0,1,2,3,4].map(i=>card(s.board[i])).join('')}</div></div><div class="seat hero-seat"><div class="hero-cards" aria-label="Your hole cards">${s.hero.map(c=>card(c,true)).join('')}</div><span class="seat-label"><b>You</b> · ${s.heroPosition}</span></div></div><div class="scene-meta"><span><b>${s.heroPosition} vs ${s.villainPosition}</b></span><span>${s.potType}</span><span>No rake</span></div><div class="history"><div class="section-row"><h3>Action leading here</h3></div><div class="history-list">${s.history.map(([street,text],i)=>`<div class="history-step ${i===s.history.length-1?'current':''}"><span class="dot" aria-hidden="true"></span><span class="street">${street}</span><p>${text}</p></div>`).join('')}</div></div></section>`}
function villainProfile(s){const p=profileFor(s);return `<section class="villain-profile chart-profile" aria-label="Villain tendencies"><div class="section-row"><div><span class="eyebrow">Your opponent</span><h3>${p.name}</h3></div><span class="small-pill">${p.style}</span></div><p class="profile-sample">${p.sample}</p><ul class="tendency-notes">${p.observations.map(x=>`<li>${x}</li>`).join('')}</ul><details class="profile-caution"><summary>How reliable is this read?</summary><p>${p.caution}</p></details><p class="profile-disclaimer">Fictional training observations. Use them to form a working range.</p></section>`}
function cellStatus(hand,ctx){if(state.result){if(state.result.matched.includes(hand))return 'matched';if(state.result.missing.includes(hand))return 'missed';if(state.result.extra.includes(hand))return 'extra'}return !ctx.legal.has(hand)?'blocked':state.selected.includes(hand)?'selected':''}
function chartView(s){const ctx=chartContext(s);return `<section class="chart-panel" aria-label="Range chart exercise"><div class="answer-kicker"><span class="eyebrow">Your range read</span><span>${state.view==='review'?'Review':s.title}</span></div><h2>What is villain’s range here?</h2><p class="question-sub">Click a hand to include it. Click again to remove it.</p><p class="chart-scope-note">Use the stated starting pool and villain’s tendencies. <button data-action="show-start">View starting range</button></p><div class="chart-key"><span><i class="key-pair"></i>Pairs · diagonal</span><span><i class="key-suited"></i>Suited · above</span><span><i class="key-offsuit"></i>Offsuit · below</span></div><p class="mobile-chart-tip">Swipe the chart sideways to reach every hand.</p><div class="range-chart-scroll" tabindex="0" aria-label="Scrollable starting-hand chart"><div class="range-matrix" role="group" aria-label="13 by 13 starting-hand range chart">${HAND_CELLS.map(({hand,kind},i)=>{const status=cellStatus(hand,ctx),selected=state.selected.includes(hand);return `<button type="button" class="range-cell ${kind} ${status}" data-hand="${hand}" data-index="${i}" tabindex="${i===0?0:-1}" aria-label="${hand}, ${kind}${!ctx.legal.has(hand)?', blocked by known cards':''}${state.result?`, ${status==='matched'?'included correctly':status==='missed'?'missing from your range':status==='extra'?'outside the model':'not in model'}`:''}" aria-pressed="${selected}" ${!ctx.legal.has(hand)&&!state.result?'aria-disabled="true"':''}><span>${hand}</span>${state.result&&['matched','missed','extra'].includes(status)?`<small aria-hidden="true">${status==='matched'?'✓':status==='missed'?'+':'×'}</small>`:''}</button>`}).join('')}</div></div>${state.result?`<div class="result-key"><span class="good">✓ Included correctly</span><span class="missing">+ Missed</span><span class="too-wide">× Outside model</span></div>`:`<div class="chart-toolbar"><span id="selection-summary" aria-live="polite">${state.selected.length} hand type${state.selected.length===1?'':'s'} selected</span><div><button class="text-button" data-action="undo" ${state.undo.length?'':'disabled'}>Undo</button><button class="text-button" data-action="clear" ${state.selected.length?'':'disabled'}>Clear</button></div></div>`}<p class="chart-instruction">A cell means at least one combo of that hand can be present. Suits and blockers are explained after you submit.</p><div id="hand-inspector">${inspectorView(s)}</div>${state.error?`<p class="alert" role="alert">${state.error}</p>`:''}${state.result?feedbackView(s):`<button class="primary" data-action="submit">Check my range</button><div class="answer-actions"><button class="text-button" data-action="hint">${icon('bulb')}${state.showHint?'Hide hint':'Give me a hint'}</button><button class="text-button" data-action="reveal">Show working range</button></div>${state.showHint?`<div class="hint" role="status">${s.hint}</div>`:''}`}<details class="starting-range"><summary>Starting range for this exercise</summary><p>${s.scope}</p><div class="range-tags">${s.startingRange.map(t=>`<span class="range-tag">${handLabel(t)}</span>`).join('')}</div><p>Hands outside this starting pool are excluded from this exercise’s model. You can still select them and inspect the feedback.</p></details></section>`}
function explanationBody(e){return `<p>${escape(e.reason)}</p>${e.evidence?`<blockquote><span>Clue from the profile</span>${escape(e.evidence)}</blockquote>`:''}${e.blockers.length?`<p class="blocker-note"><b>Blocking cards:</b> ${e.blockers.map(b=>`${inlineCard(b.card)} in ${b.source}`).join(' · ')}. ${e.removed.length?`Removed from the betting model: ${e.removed.map(c=>combo(c)).join(', ')}.`:''}</p>`:''}<p class="reason-takeaway"><b>What to change:</b> ${escape(e.takeaway)}</p>`}
function inspectorView(s){if(!state.inspected)return '<p class="inspector-placeholder">Use arrow keys to move across the chart; Space selects a hand.</p>';const hand=state.inspected,ctx=chartContext(s);if(!state.result)return `<div class="hand-inspector"><strong>${hand}</strong><span>${ctx.legal.has(hand)?'A hand type can include only some suits in a betting range.':'The visible cards rule out every combination of this hand.'}</span></div>`;const e=explainHand(s,hand,ctx);return `<div class="hand-inspector solution-inspector"><strong>${hand} · ${e.title}</strong>${explanationBody(e)}${e.live.length?`<p class="suit-detail">${e.live.length} exact combo${e.live.length===1?'':'s'} in this model:</p><div class="combo-grid">${e.live.map(c=>`<span class="combo-chip">${combo(c)}</span>`).join('')}</div>`:''}<button class="text-button" data-ask="${hand}">Ask Codex about ${hand} ↗</button></div>`}
function feedbackView(s){const r=state.result;return `<div class="feedback ${r.correct&&!r.revealed?'':'wrong'}" id="chart-feedback" role="status" tabindex="-1"><div class="feedback-title">${r.revealed?'The working range.':r.correct?state.hinted?'Range matched, with help.':'Your range matches the model.':'Compare your read with the model.'}</div>${r.revealed?`<p>${r.expected.length} hand types are included. Click any chart cell to inspect the reasoning and exact suits.</p>`:`<div class="range-score"><b>${r.score}%</b><span>range match</span></div><p>${r.matched.length} matched · ${r.missing.length} missed · ${r.extra.length} outside the model</p>`}</div>${r.extra.length?`<a class="explanation-jump" href="#mistake-explanations">Read why your ${r.extra.length} extra selection${r.extra.length===1?' was':'s were'} marked wrong ↓</a>`:''}<button class="primary" data-action="next">${state.view==='review'&&queue().length===0?'Finish review':state.sessionLength&&state.index===state.order.length-1?'Finish session':'Next hand'}</button>${s.counterpart?`<button class="outline-button compare-button" data-compare="${s.counterpart}">${s.comparisonLabel||'Same cards, different villain'}</button>`:''}<p class="small-info">${r.correct&&!state.hinted&&!r.revealed?'Saved as a complete, unaided match.':'Saved for mistake review. A complete match without help clears this hand.'}</p>`}
function reasonCard(s,hand){const e=explainHand(s,hand);return `<article class="reason-card"><div class="reason-card-title"><h3><span class="hand-token">${hand}</span>${e.title}</h3><button class="text-button" data-ask="${hand}" aria-label="Ask Codex about ${hand}">Ask Codex ↗</button></div>${explanationBody(e)}</article>`}
function solutionView(s){const r=state.result;return `<section class="breakdown" id="mistake-explanations"><div class="section-row"><h2>${r.extra.length?'Why your selections were marked wrong':'Understand your range'}</h2><button class="outline-button" data-ask="">Ask about this spot ↗</button></div><p class="solution-prose">${r.extra.length?'These hands are outside this exercise’s betting range for the reasons below. A model exclusion does not mean a real opponent could never play the hand.':'Click any hand in the chart to inspect its reasoning and exact suits.'}</p>${r.extra.length?`<div class="reason-list">${r.extra.slice(0,4).map(h=>reasonCard(s,h)).join('')}</div>${r.extra.length>4?`<details class="more-reasons"><summary>Explain ${r.extra.length-4} more selections</summary><div class="reason-list">${r.extra.slice(4).map(h=>reasonCard(s,h)).join('')}</div></details>`:''}`:''}${r.missing.length?`<details class="more-reasons"><summary>Why ${r.missing.length} missed hand${r.missing.length===1?' belongs':'s belong'} in the range</summary><div class="reason-list">${r.missing.map(h=>reasonCard(s,h)).join('')}</div></details>`:''}<h3 class="line-lesson">Why this range fits the line</h3><p class="solution-prose">${s.lesson}</p><details><summary>Exact assumptions used for this feedback</summary><p class="solution-prose">${s.model}</p><p class="formula-note">This is one simplified model of the fictional opponent. Observations and actions alone do not determine a unique real-world range.</p></details><div class="selection-lists">${[['Included correctly',r.matched,'good'],['Hands you missed',r.missing,'missing'],['Outside this model',r.extra,'too-wide']].map(([label,hands,color])=>`<div><h3 class="${color}">${label} · ${hands.length}</h3><div class="hand-tags">${hands.length?hands.map(h=>`<button data-inspect="${h}" class="outline-button">${h}</button>`).join(''):'<span class="muted">None</span>'}</div></div>`).join('')}</div></section>`}
function spotPrompt(){return buildSpotQuestion({scenario:current(),selected:state.selected,result:state.result,hand:state.coachHand,question:state.coachQuestion})}
function coachView(s){if(!state.coachOpen)return '';const prompt=spotPrompt();return `<section class="coach-panel" id="ask-codex" aria-labelledby="coach-heading"><div class="section-row"><div><span class="eyebrow">Discuss this spot</span><h2 id="coach-heading">Ask Codex</h2></div><button class="text-button" data-action="close-coach" aria-label="Close Ask Codex">Close ×</button></div><p>Write your question here. Open a new Codex draft with the cards, bets, opponent notes, and your range attached, then send it there.</p><p class="coach-context"><b>${escape(s.title)}</b> · ${streets[s.street]} · ${s.heroPosition} vs ${s.villainPosition}</p><label for="coach-hand">Focus on a hand <span class="muted">(optional)</span></label><select id="coach-hand"><option value="">The whole spot</option>${HAND_CELLS.map(c=>`<option value="${c.hand}" ${state.coachHand===c.hand?'selected':''}>${c.hand}</option>`).join('')}</select><label for="coach-question">Your question</label><textarea id="coach-question" rows="3" maxlength="1200" placeholder="Why would this player check JJ instead of betting it?">${escape(state.coachQuestion)}</textarea><div class="coach-suggestions"><button class="outline-button" data-coach-question="Why does this hand not fit the betting line?">Why not this hand?</button><button class="outline-button" data-coach-question="Which blockers matter here, and which exact combinations do they remove?">Explain the blockers</button><button class="outline-button" data-coach-question="What different opponent tendencies would make my range reasonable?">What would change the range?</button></div><div class="coach-actions"><a class="primary" id="open-codex" href="${escape(codexDraftUrl(prompt))}">Open draft in Codex ↗</a><button class="outline-button" data-action="copy-spot">Copy question + spot</button></div><p class="coach-note">Replies appear in Codex. To continue an existing Codex chat, copy the question and paste it into that chat. ${!state.result?'Getting help before checking marks this attempt as assisted.':''}</p><p class="coach-status" role="status">${escape(state.coachStatus)}</p><details id="coach-preview"><summary>Review or manually copy the attached spot</summary><textarea id="coach-prompt" rows="12" readonly aria-label="Question and full spot for Codex">${escape(prompt)}</textarea></details></section>`}
function openCoach(hand=''){state.coachOpen=true;state.coachHand=hand;state.coachStatus='';state.coachQuestion=hand?`Why ${state.result?.extra.includes(hand)?'is':'does'} ${hand} ${state.result?.extra.includes(hand)?'outside the model':'fit or not fit this betting range'}?`:'';render();document.querySelector('#ask-codex')?.scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#coach-question')?.focus({preventScroll:true})}
function updateCoachDraft(){state.coachStatus='';const prompt=spotPrompt();document.querySelector('#open-codex')?.setAttribute('href',codexDraftUrl(prompt));const preview=document.querySelector('#coach-prompt');if(preview)preview.value=prompt;const status=document.querySelector('.coach-status');if(status)status.textContent=''}
function markCoachAssisted(){if(!state.result)state.hinted=true}
async function copySpot(){markCoachAssisted();try{await navigator.clipboard.writeText(spotPrompt());state.coachStatus='Copied. Paste into your Codex chat and send your question.'}catch{state.coachStatus='Clipboard unavailable. Select and copy the attached spot below.';const details=document.querySelector('#coach-preview');if(details)details.open=true;const field=document.querySelector('#coach-prompt');field?.focus();field?.select()}const status=document.querySelector('.coach-status');if(status)status.textContent=state.coachStatus}
function bindAskButtons(){document.querySelectorAll('[data-ask]').forEach(el=>el.onclick=()=>openCoach(el.dataset.ask))}
function lessonsView(){return `<div class="title-row"><div><h1>Read the player. Build the range.</h1><p class="subtitle">Your answer is the set of hand types you select on the chart.</p></div></div><div class="lessons-grid"><article class="lesson-card"><div class="lesson-number">01 / READ THE CHART</div><h2>One cell, one hand type.</h2><p>Pairs run diagonally from AA to 22. Suited hands sit above that line; offsuit hands sit below it.</p><div class="formula">AA · AKs · AKo</div><p>AKs and AKo are separate choices. Click both if both can be in villain’s range. A cell is selected when at least one legal combo of that hand type belongs.</p></article><article class="lesson-card"><div class="lesson-number">02 / READ THE OPPONENT</div><h2>Follow the whole line.</h2><p>Start with position and the earlier actions. Ask what this player tends to bet, check, call, and raise. A wide preflop range can become narrow after several barrels.</p><p>Each drill names a starting pool to keep feedback concrete. The exact continuation model is hidden until you submit. It is an illustrative assumption, not a solver output.</p></article><article class="lesson-card"><div class="lesson-number">03 / RESPECT THE SUITS</div><h2>Suited does not mean every suit.</h2><p>On a two-heart board, KQs might be included only as K♥Q♥. Select KQs if that combo fits. Feedback then shows the exact suits in the model.</p><p>Blockers can remove a whole cell if they eliminate every relevant combo. A hand can be physically possible in other suits yet absent from this particular betting range.</p></article></div><article class="lesson-wide"><h2>Use feedback to refine the read.</h2><p><strong>✓ Green:</strong> you included a hand that fits the working model. <strong>+ Amber:</strong> a hand in the model was missing. <strong>× Pink:</strong> your range included a hand outside this model. Click any cell after grading to see why.</p><p>Range match compares the hand types you selected with those in the target model: shared hand types divided by all hand types in either range. Leaving the whole chart empty or selecting everything does not earn easy credit for correctly excluded cells.</p><p>Real opponents mix frequencies and sometimes surprise you. The observations are fictional and incomplete; a few showdowns never prove an exact range. Use these drills to practice forming and checking a hypothesis.</p><button class="primary guide-start" data-nav="train">Practice a range</button></article>`}
function progressView(){const st=stats(),recent=progress.chart.attempts.slice(-10).reverse();return `<div class="title-row"><div><h1>Your range reading.</h1><p class="subtitle">Chart practice has its own scores. Your earlier practice history is preserved.</p></div><button class="outline-button" data-nav="train">Keep practicing</button></div><div class="stat-grid"><div class="stat"><b>${st.total}</b><span>Charts attempted</span></div><div class="stat"><b>${st.average===null?'—':st.average+'%'}</b><span>Average range match</span></div><div class="stat"><b>${st.mastered} / ${scenarios.length}</b><span>Complete unaided matches</span></div><div class="stat"><b>${queue().length}</b><span>Charts to revisit</span></div></div><section class="progress-card"><h2>Practice by street</h2>${Object.entries(streets).filter(([k])=>k!=='all'&&scenarios.some(s=>s.street===k)).map(([k,label])=>{const all=scenarios.filter(s=>s.street===k),n=all.filter(s=>progress.chart.records[s.id]?.mastered).length;return `<div class="topic-progress"><span>${label}</span><div class="progress-track" role="progressbar" aria-label="${label} mastery" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${all.length}"><span style="width:${n/all.length*100}%"></span></div><span>${n} / ${all.length}</span></div>`}).join('')}<button class="outline-button" data-nav="review">Review missed ranges</button></section><section class="progress-card"><h2>Recent charts</h2>${recent.length?`<table class="range-table"><thead><tr><th scope="col">Hand</th><th scope="col">Result</th></tr></thead><tbody>${recent.map(a=>`<tr><td>${escape(scenarioById.get(a.id)?.title||a.id)}</td><td>${a.revealed?'Range revealed':`${a.score}%${a.hinted?' · help used':''}`}</td></tr>`).join('')}</tbody></table>`:'<p class="subtitle">Your first submitted range starts your chart history.</p>'}<p class="formula-note">Reveals do not enter average match scores. Hints and Codex drafts count as assisted practice. A complete unaided match clears a chart from review. Progress stays in this browser.</p>${progress.attempts.length?`<details><summary>Earlier combo practice · ${progress.attempts.length} attempts preserved</summary><p class="formula-note">${progress.attempts.filter(a=>a.correct&&!a.hinted&&!a.revealed).length} unaided correct attempts. Earlier combo-counting and group-selection records remain saved separately; they do not count as completed range charts.</p></details>`:''}<button class="text-button" data-action="reset-confirm">Reset chart progress</button>${state.confirmReset?'<div class="reset-confirm"><span>Clear chart attempts and review? Earlier combo history will be kept.</span><button class="outline-button" data-action="reset">Clear chart progress</button><button class="text-button" data-action="cancel-reset">Cancel</button></div>':''}</section>`}
function updateInspector(){const el=document.querySelector('#hand-inspector');if(el)el.innerHTML=inspectorView(current());bindAskButtons()}
function updateChart(){if(!state.error)document.querySelector('.chart-panel [role="alert"]')?.remove();document.querySelectorAll('[data-hand]').forEach(el=>{const selected=state.selected.includes(el.dataset.hand);el.classList.toggle('selected',selected&&!state.result);el.setAttribute('aria-pressed',String(selected))});const summary=document.querySelector('#selection-summary');if(summary)summary.textContent=`${state.selected.length} hand type${state.selected.length===1?'':'s'} selected`;const undo=document.querySelector('[data-action="undo"]'),clear=document.querySelector('[data-action="clear"]');if(undo)undo.disabled=!state.undo.length;if(clear)clear.disabled=!state.selected.length;updateInspector();if(state.coachOpen)updateCoachDraft()}
function bind(){
 bindAskButtons();bindSpotLinks();
 document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{state[el.dataset.filter]=el.value;rebuildOrder();render()});
 const unseen=document.querySelector('[data-unseen]');if(unseen)unseen.onchange=()=>{state.unseen=unseen.checked;rebuildOrder();render()};
 document.querySelectorAll('[data-library-street]').forEach(el=>el.onclick=()=>{Object.assign(state,{street:el.dataset.libraryStreet,collection:'all',style:'all',difficulty:'all',situation:'all',unseen:false,view:'train'});rebuildOrder();render();window.scrollTo({top:0,behavior:'instant'})});
 const search=document.querySelector('#library-search');if(search)search.oninput=()=>{state.librarySearch=search.value;document.querySelector('#library-results').innerHTML=libraryResults();bindSpotLinks()};
 const coachQuestion=document.querySelector('#coach-question');if(coachQuestion)coachQuestion.oninput=()=>{state.coachQuestion=coachQuestion.value;updateCoachDraft()};
 const coachHand=document.querySelector('#coach-hand');if(coachHand)coachHand.onchange=()=>{state.coachHand=coachHand.value;updateCoachDraft()};
 const openCodex=document.querySelector('#open-codex');if(openCodex)openCodex.onclick=()=>{markCoachAssisted();state.coachStatus='Send the prepared draft in Codex. If it did not open, use Copy question + spot.';document.querySelector('.coach-status').textContent=state.coachStatus};
 document.querySelectorAll('[data-coach-question]').forEach(el=>el.onclick=()=>{state.coachQuestion=el.dataset.coachQuestion;coachQuestion.value=state.coachQuestion;updateCoachDraft();coachQuestion.focus()});
 document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>nav(el.dataset.nav));
 document.querySelectorAll('[data-street]').forEach(el=>el.onclick=()=>setStreet(el.dataset.street));
 document.querySelectorAll('[data-compare]').forEach(el=>el.onclick=()=>compare(el.dataset.compare));
 document.querySelectorAll('[data-inspect]').forEach(el=>el.onclick=()=>{state.inspected=el.dataset.inspect;updateInspector();document.querySelector('#hand-inspector')?.scrollIntoView({behavior:'smooth',block:'nearest'})});
 document.querySelectorAll('[data-hand]').forEach(el=>{el.onclick=()=>toggleHand(el.dataset.hand);el.onkeydown=e=>{const i=Number(el.dataset.index),row=Math.floor(i/13),col=i%13;let n=i;if(e.key==='ArrowRight')n=row*13+Math.min(12,col+1);else if(e.key==='ArrowLeft')n=row*13+Math.max(0,col-1);else if(e.key==='ArrowDown')n=Math.min(12,row+1)*13+col;else if(e.key==='ArrowUp')n=Math.max(0,row-1)*13+col;else if(e.key==='Home')n=e.ctrlKey?0:row*13;else if(e.key==='End')n=e.ctrlKey?168:row*13+12;else return;e.preventDefault();document.querySelectorAll('[data-hand]').forEach(b=>b.tabIndex=Number(b.dataset.index)===n?0:-1);document.querySelector(`[data-index="${n}"]`)?.focus()}});
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{switch(el.dataset.action){case'start-session':startSession();break;case'copy-spot':copySpot();break;case'close-coach':state.coachOpen=false;render();document.querySelector('[data-ask]')?.focus();break;case'show-start':{const details=document.querySelector('.starting-range');details.open=true;details.scrollIntoView({behavior:'smooth',block:'nearest'});break;}case'submit':submit();break;case'reveal':submit(true);break;case'next':next();break;case'hint':state.hinted=true;state.showHint=!state.showHint;render();break;case'clear':if(!state.result)recordSelection([]);break;case'undo':if(state.undo.length&&!state.result){state.selected=state.undo.pop();updateChart()}break;case'shuffle':shuffle();break;case'all-hands':Object.assign(state,{street:'all',collection:'all',style:'all',difficulty:'all',situation:'all',unseen:false});rebuildOrder();nav('train');break;case'reset-confirm':state.confirmReset=true;render();break;case'cancel-reset':state.confirmReset=false;render();break;case'reset':progress.chart={attempts:[],records:{}};state.confirmReset=false;save();render();break;}})
}
render();
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const readState=()=>{const s=current(),p=s?profileFor(s):null;return{view:state.view,streetFilter:state.street,question:s?{id:s.id,title:s.title,street:s.street,board:s.board,hero:s.hero,positions:{hero:s.heroPosition,villain:s.villainPosition},history:s.history,profile:p?{name:p.name,style:p.style,sample:p.sample,observations:p.observations,caution:p.caution}:null,startingRange:s.startingRange}:null,selectedHands:state.selected,result:state.result?{correct:state.result.correct,score:state.result.score,matched:state.result.matched,missing:state.result.missing,extra:state.result.extra}:null,progress:stats()}};
 const tools=[
 {name:'find_practice_spots',title:'Find library spots',description:'Find practice spots by title, street, position or stable ID. Returns at most 24 metadata entries, without hidden ranges.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{const q=String(input.query).toLowerCase();const matches=scenarios.filter(s=>`${s.id} ${s.title} ${s.street} ${s.heroPosition} ${s.villainPosition}`.toLowerCase().includes(q));return {total:matches.length,spots:matches.slice(0,24).map(s=>({id:s.id,title:s.title,street:s.street,style:s.style,difficulty:s.difficulty}))}}},
 {name:'open_practice_spot',title:'Open a library spot',description:'Open a specific range chart by its stable library ID. Discards any unsubmitted selection.',inputSchema:{type:'object',properties:{id:{type:'string'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!scenarioById.has(input.id))throw new Error('Unknown spot ID.');openScenario(input.id);return readState()}},
 {name:'read_spot_question',title:'Read the prepared spot question',description:'Read the question prepared in the visible Ask Codex panel, including the current cards, betting history, profile, selected range and feedback only after grading.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>{if(!state.coachOpen||!current())throw new Error('Open Ask Codex for a spot first.');return {prompt:spotPrompt()}}},
 {name:'read_training_state',title:'Read the current range exercise',description:'Read the visible scenario, profile, starting pool, and selected hands. Does not reveal the target before submission.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:readState},
 {name:'start_practice',title:'Start range-chart practice',description:'Open a range chart for a chosen street. Discards any unsubmitted chart.',inputSchema:{type:'object',properties:{street:{type:'string',enum:Object.keys(streets)}},required:['street'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Object.hasOwn(streets,input?.street))throw new Error('Choose a valid street.');Object.assign(state,{street:input.street,collection:'all',style:'all',difficulty:'all',situation:'all',unseen:false});rebuildOrder();nav('train');return readState()}},
 {name:'select_range_hands',title:'Select hands on the range chart',description:'Replace the visible chart selection with specific hand classes such as AA, AKs, and AKo. Does not grade or save an attempt.',inputSchema:{type:'object',properties:{hands:{type:'array',items:{type:'string'},uniqueItems:true}},required:['hands'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!['train','review'].includes(state.view)||!current()||state.result)throw new Error('Open an unanswered chart.');const hands=validateSelection(input?.hands),ctx=chartContext(current());if(hands.some(h=>!ctx.legal.has(h)))throw new Error('Known cards make at least one selected hand impossible.');recordSelection(hands);return readState()}},
 {name:'submit_range_chart',title:'Check the selected range',description:'Grade the current chart against the working model, reveal feedback, and save a browser-local practice attempt.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(!['train','review'].includes(state.view)||!current()||state.result||!state.selected.length)throw new Error('Select hands on an unanswered chart first.');submit();return readState()}},
 {name:'next_practice_hand',title:'Continue to the next hand',description:'Move to the next chart after checking the current range.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(!['train','review'].includes(state.view)||!state.result)throw new Error('Check the current chart first.');next();return readState()}}
 ];
 for(const def of tools){try{Promise.resolve(document.modelContext.registerTool(def,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
